import{_ as t,a0 as p,w as d,s as o,I as a,x as e,a1 as i,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"适用于初学者的基本 kubectl 和 Helm 命令 | LCTT x X-CMD","titleTemplate":false,"description":"适用于初学者的基本 kubectl 和 Helm 命令 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"适用于初学者的基本 kubectl 和 Helm 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"适用于初学者的基本 kubectl 和 Helm 命令 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200211 Basic kubectl and Helm commands for beginners","title":"适用于初学者的基本 kubectl 和 Helm 命令","tag":"202003","desc":""},"relativePath":"202003/20200211 Basic kubectl and Helm commands for beginners.md","filePath":"[post].md"}'),u={name:"202003/20200211 Basic kubectl and Helm commands for beginners.md"};function k(b,s,h,c,g,m){const n=p("Link");return d(),o("div",null,[s[28]||(s[28]=a("h1",{id:"适用于初学者的基本-kubectl-和-helm-命令",tabindex:"-1"},[e("适用于初学者的基本 kubectl 和 Helm 命令 "),a("a",{class:"header-anchor",href:"#适用于初学者的基本-kubectl-和-helm-命令","aria-label":"Permalink to “适用于初学者的基本 kubectl 和 Helm 命令”"},"​")],-1)),s[29]||(s[29]=a("blockquote",null,[a("p",null,"去杂货店“采购”这些命令，你需要用这些 Kubernetes 工具来入门。")],-1)),s[30]||(s[30]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202003/18/113120adp34myy90eb944b.jpg",alt:""})],-1)),s[31]||(s[31]=a("p",null,[e("最近，我丈夫告诉我他即将要去参加一个工作面试，面试时他需要在计算机上运行一些基本命令。他对这场面试感到焦虑，但是对于他来说，学习和记住事情的最好方法是将不了解的事物比喻为非常熟悉的事物。因为我们的谈话是在我逛杂货店试图决定当晚要烹饪的食物之后进行的，所以这启发我用一次去杂货店的行程来介绍 "),a("code",null,"kubectl"),e(" 和 "),a("code",null,"helm"),e(" 命令。")],-1)),a("p",null,[i(n,{href:"https://helm.sh/"},{default:l(()=>[...s[0]||(s[0]=[e("Helm",-1)])]),_:1}),s[2]||(s[2]=e("（“舵轮”）是在 Kubernetes（来自希腊语，意思是“舵手” 或 “领航员”）中管理应用程序的工具。你可以轻松地使用你的应用程序信息来部署“",-1)),s[3]||(s[3]=a("ruby",null,[e("海图"),a("rt",null,"chart")],-1)),s[4]||(s[4]=e("”，从而可以在你的 Kubernetes 环境中几分钟之内让它们就绪并预配置好。在学习新知识时，查看示例的“海图”以了解其用法总是很有帮助的，因此，如果有时间，请查看这些成型的“",-1)),i(n,{href:"https://github.com/helm/charts/tree/master/stable"},{default:l(()=>[...s[1]||(s[1]=[e("海图",-1)])]),_:1}),s[5]||(s[5]=e("”。（LCTT 译注：Kubernetes 生态中大量使用了和航海有关的比喻，因此本文在翻译时也采用了这些比喻）",-1))]),a("p",null,[i(n,{href:"https://kubernetes.io/docs/reference/kubectl/kubectl/"},{default:l(()=>[...s[6]||(s[6]=[e("kubectl",-1)])]),_:1}),s[8]||(s[8]=e(" 是与 Kubernetes 环境交互的命令行界面，允许你配置和管理集群。它需要一些配置才能在环境中工作，因此请仔细阅读其",-1)),i(n,{href:"https://kubernetes.io/docs/reference/kubectl/overview/"},{default:l(()=>[...s[7]||(s[7]=[e("文档",-1)])]),_:1}),s[9]||(s[9]=e("以了解你需要做什么。",-1))]),a("p",null,[s[11]||(s[11]=e("我会在示例中使用命名空间，你可以在我的文章《",-1)),i(n,{href:"https://linux.cn/article-11749-1.html"},{default:l(()=>[...s[10]||(s[10]=[e("Kubernetes 命名空间入门",-1)])]),_:1}),s[12]||(s[12]=e("》中了解它。",-1))]),s[32]||(s[32]=r(`<p>现在我们已经准备好了，让我们开始 <code>kubectl</code>和 <code>helm</code> 基本命令的购物之旅！</p><h3 id="用-helm-列出清单" tabindex="-1">用 Helm 列出清单 <a class="header-anchor" href="#用-helm-列出清单" aria-label="Permalink to “用 Helm 列出清单”">​</a></h3><p>你去商店之前要做的第一件事是什么？好吧，如果你做事有条理，会创建一个“清单”。同样，这是我将解释的第一个基本的 Helm 命令。</p><p>在一个用 Helm 部署的应用程序中，<code>list</code> 命令提供有关应用程序当前版本的详细信息。在此示例中，我有一个已部署的应用程序：Jenkins CI/CD 应用程序。运行基本的 <code>list</code> 命令总是会显示默认的命名空间。由于我没有在默认的命名空间中部署任何内容，因此不会显示任何内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$helm list</span></span>
<span class="line"><span>NAME    NAMESPACE    REVISION    UPDATED    STATUS    CHART    APP VERSION</span></span></code></pre></div><p>但是，如果运行带有额外标志的命令，则会显示我的应用程序和信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$helm list --all-namespaces</span></span>
<span class="line"><span>NAME     NAMESPACE  REVISION  UPDATED                   STATUS      CHART           APP  VERSION</span></span>
<span class="line"><span>jenkins  jenkins        1         2020-01-18 16:18:07 EST   deployed    jenkins-1.9.4   lts</span></span></code></pre></div><p>最后，我可以指示 <code>list</code> 命令只检查我想从中获取信息的命名空间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$helm list --namespace jenkins</span></span>
<span class="line"><span>NAME     NAMESPACE  REVISION  UPDATED                   STATUS    CHART          APP VERSION</span></span>
<span class="line"><span>jenkins    jenkins      1              2020-01-18 16:18:07 EST  deployed  jenkins-1.9.4  lts</span></span></code></pre></div><p>现在我有了一个清单，并且知道该清单上有什么，我可以使用 <code>get</code> 命令来“获取”我的物品！我会从 Kubernetes 集群开始，看看我能从中获取到什么？</p><h3 id="用-kubectl-获取物品" tabindex="-1">用 Kubectl 获取物品 <a class="header-anchor" href="#用-kubectl-获取物品" aria-label="Permalink to “用 Kubectl 获取物品”">​</a></h3><p><code>kubectl get</code> 命令提供了有关 Kubernetes 中许多事物的信息，包括“<ruby>吊舱<rt>Pod</rt></ruby>”、节点和命名空间。同样，如果没有指定命名空间标志，就会使用默认的命名空间。首先，我获取集群中的命名空间以查看正在运行的命名空间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl get namespaces</span></span>
<span class="line"><span>NAME             STATUS   AGE</span></span>
<span class="line"><span>default          Active   53m</span></span>
<span class="line"><span>jenkins          Active   44m</span></span>
<span class="line"><span>kube-node-lease  Active   53m</span></span>
<span class="line"><span>kube-public      Active   53m</span></span>
<span class="line"><span>kube-system      Active   53m</span></span></code></pre></div><p>现在我已经知道了在我的环境中运行的有哪些命名空间了，接下来获取节点并查看有多少个节点正在运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl get nodes</span></span>
<span class="line"><span>NAME       STATUS   ROLES       AGE   VERSION</span></span>
<span class="line"><span>minikube   Ready    master  55m   v1.16.2</span></span></code></pre></div><p>我有一个节点正在运行，这主要是因为我的 Minikube 运行在一台小型服务器上。要得到在我的这一个节点上运行的“吊舱”可以这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl get pods</span></span>
<span class="line"><span>No resources found in default namespace.</span></span></code></pre></div><p>啊哦，它是空的。我将通过以下方式获取 Jenkins 命名空间中的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl get pods --namespace jenkins</span></span>
<span class="line"><span>NAME                      READY  STATUS   RESTARTS  AGE</span></span>
<span class="line"><span>jenkins-7fc688c874-mh7gv  1/1    Running  0         40m</span></span></code></pre></div><p>好消息！这里发现了一个“吊舱”，它还没有重新启动过，已运行了 40 分钟了。好的，如今我知道“吊舱”已经装好，所以我想看看用 Helm 命令可以得到什么。</p><h3 id="用-helm-获取信息" tabindex="-1">用 Helm 获取信息 <a class="header-anchor" href="#用-helm-获取信息" aria-label="Permalink to “用 Helm 获取信息”">​</a></h3><p><code>helm get</code> 命令稍微复杂一点，因为这个“获取”命令所需要的不仅仅是一个应用程序名称，而且你可以从应用程序中请求多个内容。我会从获取用于制作该应用程序的值开始，然后展示“获取全部”的操作结果的片段，该操作将提供与该应用程序相关的所有数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$helm get values jenkins -n jenkins</span></span>
<span class="line"><span>USER-SUPPLIED VALUES:</span></span>
<span class="line"><span>null</span></span></code></pre></div><p>由于我只安装了最小限度的稳定版，因此配置没有更改。如果我运行“获取全部”命令，我将得到所有的“海图”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$helm get all jenkins -n jenkins</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/helm-get-all.png" alt="output from helm get all command" title="output from helm get all command"></p><p>这会产生大量数据，因此我始终建议保留一份 Helm “海图”的副本，以便你可以查看“海图”中的模板。我还创建自己的值来了解自己所拥有的。</p><p>现在，我把所有的商品都放在购物车中了，我会检查一下“描述”它们包含什么的标签。这些示例仅与 <code>kubectl</code> 命令有关，它们描述了我通过 Helm 部署的内容。</p><h3 id="用-kubectl-查看描述" tabindex="-1">用 kubectl 查看描述 <a class="header-anchor" href="#用-kubectl-查看描述" aria-label="Permalink to “用 kubectl 查看描述”">​</a></h3><p>正如我使用“获取”命令（该命令可以描述 Kubernetes 中的几乎所有内容）所做的那样，我将示例限定到命名空间、“吊舱”和节点上。由于我知道它们每一个是什么，因此这很容易。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl describe ns jenkins</span></span>
<span class="line"><span>Name:           jenkins</span></span>
<span class="line"><span>Labels:         &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>Annotations:  &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>Status:         Active</span></span>
<span class="line"><span>No resource quota.</span></span>
<span class="line"><span>No resource limits.</span></span></code></pre></div><p>我可以看到我的命名空间的名称，并且它是活动的，没有资源或限额限制。</p><p><code>describe pods</code> 命令会产生大量信息，因此我这里提供的是一小段输出。如果你在不使用“吊舱”名称的情况下运行该命令，它将返回名称空间中所有“吊舱”的信息，这可能会很麻烦。因此，请确保在此命令中始终包含“吊舱”名称。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl describe pods jenkins-7fc688c874-mh7gv --namespace jenkins</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/kubectl-describe-pods.png" alt="output of kubectl-describe-pods" title="output of kubectl-describe-pods"></p><p>这会提供容器的状态、管理方式、标签以及“吊舱”中所使用的镜像（还有很多其它信息）。没有在这个简化过的输出中包括的数据有：在 Helm 配置值文件中应用的各种条件下的资源请求和限制、初始化容器和存储卷信息。如果你的应用程序由于资源不足而崩溃，或者是一个需要运行前置脚本进行配置的初始配置容器，或者生成不应该存储于纯文本 YAML 文件中的隐藏密码，则此数据很有用。</p><p>最后，我将使用 <code>describe node</code> 命令，当然，它是用来描述节点的。由于本示例只有一个名为 Minikube 的示例，因此我将使用这个名字。如果你的环境中有多个节点，则必须包含你想查找的的节点名称。</p><p>与“吊舱”一样，这个节点的命令会产生大量数据，因此我将仅包括输出片段。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl describe node minikube</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/kubectl-describe-node.png" alt="output of kubectl describe node" title="output of kubectl describe node"></p><p>注意，<code>describe node</code> 是更重要的基本命令之一。如此图所示，该命令返回统计信息，该信息指示节点何时资源用尽，并且该数据非常适合在需要扩展时（如果你的环境中没有自动扩展）向你发出警报。此输出片段中未包含的其它内容包括：对所有资源和限制的请求所占的百分比，以及资源的使用期限和分配（例如，对于我的应用程序而言）。</p><h3 id="买单" tabindex="-1">买单 <a class="header-anchor" href="#买单" aria-label="Permalink to “买单”">​</a></h3><p>使用这些命令，我完成了“购物”并得到了我想要的一切。希望这些基本命令也能在你使用 Kubernetes 的日常工作中提供帮助。</p><p>我鼓励你经常使用命令行并学习“帮助”部分中的速记标志，你可以通过运行以下命令来查看这些标志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$helm --help</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$kubectl -h</span></span></code></pre></div><h3 id="花生酱和果冻" tabindex="-1">花生酱和果冻 <a class="header-anchor" href="#花生酱和果冻" aria-label="Permalink to “花生酱和果冻”">​</a></h3><p>有些东西像花生酱和果冻一样混在一起。Helm 和 <code>kubectl</code> 就有点像那样交错在一起。</p><p>我经常在自己的环境中使用这些工具。因为它们在很多地方都有很多相似之处，所以在使用其中一个之后，我通常需要跟进另一个。例如，我可以进行 Helm 部署，并使用 <code>kubectl</code> 观察它是否失败。一起试试它们，看看它们能为你做什么。</p><hr>`,51)),a("p",null,[s[14]||(s[14]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/20/2/kubectl-helm-commands"},{default:l(()=>[...s[13]||(s[13]=[e("https://opensource.com/article/20/2/kubectl-helm-commands",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/jrepka"},{default:l(()=>[...s[15]||(s[15]=[e("Jessica Cherry",-1)])]),_:1}),s[20]||(s[20]=e(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[16]||(s[16]=[e("lujun9972",-1)])]),_:1}),s[21]||(s[21]=e(" 译者：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1}),s[22]||(s[22]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[18]||(s[18]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[23]||(s[23]=[e("LCTT",-1)])]),_:1}),s[26]||(s[26]=e(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:l(()=>[...s[24]||(s[24]=[e("Linux中国",-1)])]),_:1}),s[27]||(s[27]=e(" 荣誉推出",-1))])])}const T=t(u,[["render",k]]);export{C as __pageData,T as default};
